"""Offline scene validation using the exact shared aiTrends player (no model/API calls)."""
from pathlib import Path
import argparse,subprocess,json
P=Path(__file__).resolve().parents[1];ROOT=P.parents[1];a=argparse.ArgumentParser();a.add_argument('--work',type=Path,required=True);args=a.parse_args();args.work.mkdir(parents=True,exist_ok=True)
s=(ROOT/'skill/scripts/render.mjs').read_text().split('async function renderVideo()')[0]
s=s.replace("const KIT = fileURLToPath(new URL('../../aitrends-2d-studio/skills/make-2d-video/kit/', import.meta.url));",'const KIT = '+json.dumps(str(ROOT/'aitrends-2d-studio/skills/make-2d-video/kit'))+';')
s+='''
const browser=await chromium.launch(LAUNCH),page=await openPlayer(browser),beats=JSON.parse(fs.readFileSync(path.join(PROJECT,'story/beats.json'))),story=JSON.parse(fs.readFileSync(path.join(PROJECT,'story/shots.json'))),records=[];
for(const sh of story.shots){const sec=(sh.start+sh.end)/2;await page.evaluate(f=>window.renderFrame(f),Math.floor(sec*24));const r=await page.evaluate(async({cam})=>{const st=(await import('/project/scenes/world.js')).world(),H=st.H,sp=st.P.spider,project=sp.position.clone().project(st.camera);const id=cam==='reverse'?'lia':'nico',a=st.A[id],h=a.head.getWorldPosition(new H.Vector3()),front=new H.Vector3(1,0,0).applyQuaternion(a.head.getWorldQuaternion(new H.Quaternion())),dot=front.dot(st.camera.position.clone().sub(h).normalize());const box=new H.Box3().setFromObject(sp),size=box.getSize(new H.Vector3());return {errors:window.ERRORS,face_dot:dot,spider_ndc:project.toArray(),spider_box:size.toArray(),camera:st.camera.position.toArray(),hand:a.point().toArray(),cup:st.P.cup.position.toArray()};},{cam:sh.params.cam});records.push({shot:sh.id,beat:sh.params.beat+1,cam:sh.params.cam,seconds:sec,...r});}
const errors=records.flatMap(x=>x.errors),badFaces=records.filter(x=>['close','reverse'].includes(x.cam)&&x.face_dot<.4),badSpider=records.filter(x=>x.cam==='spider'&&(Math.abs(x.spider_ndc[0])>.8||Math.abs(x.spider_ndc[1])>.8));const result={sampled_shots:records.length,player_errors:[...new Set(errors)],bad_front_face_shots:badFaces.map(x=>x.shot),bad_spider_framing:badSpider.map(x=>x.shot),records,limitations:'Geometry/framing checks and sampled stills; not a substitute for reviewing every motion frame or listening.'};fs.writeFileSync(path.join(PROJECT,'qa/scene-numeric-audit.json'),JSON.stringify(result,null,2)+'\\n');await browser.close();server.close();if(errors.length||badFaces.length||badSpider.length)process.exitCode=1;console.log(JSON.stringify({shots:records.length,errors:errors.length,badFaces:badFaces.length,badSpider:badSpider.length}));
'''
runner=args.work/'scene-audit-runner.mjs';runner.write_text(s);subprocess.run(['node',str(runner),'--project',str(P),'--scale','0.25'],check=True)
